import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
/**
 * Whether a node counts as "current" for a human-facing listing: not
 * superseded (edged forward via `superseded-by`), and inside its valid-time
 * window. This mirrors the facade worklist's own currency filter exactly —
 * a node dropped from the worklist's live view is dropped from the index
 * too, so the two surfaces can never disagree about what "current" means.
 */
export function isCurrent(node, now) {
    return (!node.edges.some((edge) => edge.type === "superseded-by") &&
        node.validFrom <= now &&
        (node.validTo === null || node.validTo > now));
}
const INDEX_FILENAME = "INDEX.md";
const HEADER = "<!-- auto-generated by nocetta on every write — do not hand-edit -->\n# Nocetta memory index\n\n";
/** One line per node: summary (or the body's own first line, for a node
 * written before the summary field existed) — kind, scope, anchor locator
 * or "unanchored" — id's first 8 chars, the same prefix the filename and
 * every CLI report use. */
function line(node) {
    const label = (node.summary ?? node.body.split("\n")[0] ?? "").trim() || "(untitled)";
    const anchor = node.anchors[0]?.locator ?? "unanchored";
    return `- ${label} — ${node.kind}, ${node.scope}, ${anchor} (${node.id.slice(0, 8)})`;
}
/**
 * Pure rendering (Slice-style: testable without touching disk). Decision
 * 162d74f3: the committed store is read by humans too, and a folder of raw
 * frontmatter files is unreadable without the MCP server running — this is
 * the generated, always-current human affordance the old ~/.claude MEMORY.md
 * gave by hand.
 */
export function renderIndex(nodes, now = new Date().toISOString()) {
    const current = [...nodes].filter((n) => isCurrent(n, now)).sort((a, b) => a.id.localeCompare(b.id));
    return current.length > 0 ? `${HEADER}${current.map(line).join("\n")}\n` : `${HEADER}(no current memories)\n`;
}
/**
 * Regenerate the index at `<storeRoot>/INDEX.md` — the parent of MEMORY_DIR,
 * never inside it, or readStore would try to parse it as a node. Fully
 * rewritten from the current node set on every call; never hand-maintained,
 * so it can never go stale the way a hand-kept MEMORY.md would.
 */
export function writeIndex(storeRoot, nodes, now) {
    mkdirSync(storeRoot, { recursive: true });
    writeFileSync(join(storeRoot, INDEX_FILENAME), renderIndex(nodes, now), "utf8");
}
